options.onValidate:
const filterListRef = this.getWidgetRef('filterList')
const filterList = filterListRef.getOptionItems()
// const id = value.replace(/ /g,'_')
const index = filterList.findIndex(item => item.name === value)

if(!/^[a-zA-Z_]/.test(value)) callback(new Error('Start with a letter or underscore.')) 
else if(!/^[a-zA-Z_][a-zA-Z0-9 _]*$/.test(value)) callback(new Error('Only letters, numbers, spaces and underscores can be entered')) 
else if (index > -1) {
  callback(new Error('Duplicate or unusual naming'))  //fail
} else {
  callback();  //pass
}

options.onCreated:
const _this = this
async function getDocTypeList() {
  const masterTableDataTypeList = await $api.get('/admin/api/dms/easy-form/dataType/mapping', {}).then(res => res.data.data)
  const data = masterTableDataTypeList.map(item => ({
    label: $t(`marsterTable.type.${item.value}`),
    value: item.value
  }))
  return data
}
async function init() {
  const options = await getDocTypeList()
  _this.loadOptions(options)
}
init()

options.onChange:
const _this = this
const showList = {
  'volcaboury': [
    { key: 'vocabulary', isRequired: true },
  ],
  'master_table': [
    { key:'masterTable', isRequired: true },
    { key:'displayField', isRequired: true },
  ],
  'document': [
    { key: 'documentType', isRequired: true },
    { key: 'displayField', isRequired: true },
    // { key: 'isMultiple', isRequired: false }
  ]
}
function handleShow() {
  let showKeys = []
  Object.keys(showList).forEach(sKey => {
    showList[sKey].forEach(item => {
      if(!showKeys.includes(item.key)) setShow(item.key, sKey !== value, item.isRequired)
      if(sKey === value) {
        showKeys.push(item.key)
      }
    })
  })
}
function setShow(key, isHidden, isRequired) {
  const keyRef = _this.getWidgetRef(key)
  if(!keyRef) return
  isRequired = isHidden ? false : isRequired
  keyRef.setHidden(isHidden)
  keyRef.setRequired(isRequired)
}

handleShow()

